for i in range(1,9):
    try:
        df = pd.read_csv(eval(f"experiment_{i}_csv"))
        cols = df.columns.tolist()
        print(f"exp{i}: n={len(df)} cols={cols}")
        if 'ElectrolyteAdditive' in cols and 'CapacityRetention' in cols:
            print("  meanAdd=",round(df['ElectrolyteAdditive'].mean(),2),
                  "meanRet=",round(df['CapacityRetention'].mean(),3))
    except Exception as e:
        print(i,"err",e)
